ALTER TABLE product_command_admission DROP CONSTRAINT product_command_admission_command_kind_check;
ALTER TABLE product_command_admission ADD CONSTRAINT product_command_admission_command_kind_check CHECK (command_kind IN ('CREATE_PROPOSAL_GRANT', 'REVOKE_PROPOSAL_GRANT', 'STAGE_FACTOR_PROPOSAL', 'CONFIRM_FACTOR_PROPOSAL', 'FACTOR_CHAT', 'CREATE_RESEARCH_RUN', 'CANCEL_RESEARCH_RUN', 'FREEZE_STRATEGY', 'PROMOTE_STRATEGY', 'CREATE_BACKTEST_RUN', 'CANCEL_BACKTEST_RUN', 'EVALUATE_QUALIFICATION', 'CREATE_SYMBOLIC_SEARCH_EXPERIMENT', 'CREATE_PARAMETER_SEARCH_EXPERIMENT', 'ADVANCE_SEARCH_EXPERIMENT', 'CREATE_INTEGRATION', 'UPDATE_INTEGRATION_DRAFT', 'SET_INTEGRATION_SECRET', 'CLEAR_INTEGRATION_SECRET', 'RESET_INTEGRATION_DRAFT_CONTRACT', 'PUBLISH_INTEGRATION_REVISION', 'SET_INTEGRATION_LIFECYCLE', 'CREATE_CHART_CALCULATION', 'SAVE_WATCHLISTS', 'SAVE_WORKSPACE', 'SAVE_PRIVATE_FACTOR_DRAFT', 'PUBLISH_PRIVATE_FACTOR_REVISION', 'UPDATE_PRIVATE_FACTOR_DISPLAY'));
ALTER TABLE product_command_receipt DROP CONSTRAINT product_command_receipt_command_kind_check;
ALTER TABLE product_command_receipt ADD CONSTRAINT product_command_receipt_command_kind_check CHECK (command_kind IN ('CREATE_PROPOSAL_GRANT', 'REVOKE_PROPOSAL_GRANT', 'STAGE_FACTOR_PROPOSAL', 'CONFIRM_FACTOR_PROPOSAL', 'FACTOR_CHAT', 'CREATE_RESEARCH_RUN', 'CANCEL_RESEARCH_RUN', 'FREEZE_STRATEGY', 'PROMOTE_STRATEGY', 'CREATE_BACKTEST_RUN', 'CANCEL_BACKTEST_RUN', 'EVALUATE_QUALIFICATION', 'CREATE_SYMBOLIC_SEARCH_EXPERIMENT', 'CREATE_PARAMETER_SEARCH_EXPERIMENT', 'ADVANCE_SEARCH_EXPERIMENT', 'CREATE_INTEGRATION', 'UPDATE_INTEGRATION_DRAFT', 'SET_INTEGRATION_SECRET', 'CLEAR_INTEGRATION_SECRET', 'RESET_INTEGRATION_DRAFT_CONTRACT', 'PUBLISH_INTEGRATION_REVISION', 'SET_INTEGRATION_LIFECYCLE', 'CREATE_CHART_CALCULATION', 'SAVE_WATCHLISTS', 'SAVE_WORKSPACE', 'SAVE_PRIVATE_FACTOR_DRAFT', 'PUBLISH_PRIVATE_FACTOR_REVISION', 'UPDATE_PRIVATE_FACTOR_DISPLAY'));
ALTER TABLE product_command_receipt DROP CONSTRAINT product_command_receipt_outcome_kind_check;
ALTER TABLE product_command_receipt ADD CONSTRAINT product_command_receipt_outcome_kind_check CHECK (outcome_kind IN ('RESEARCH_RUN', 'STRATEGY', 'STRATEGY_PROMOTION', 'BACKTEST_RUN', 'QUALIFICATION_DECISION', 'SEARCH_EXPERIMENT', 'INTEGRATION', 'INTEGRATION_REVISION', 'CHART_CALCULATION_OPERATION', 'WATCHLIST_REVISION', 'WORKSPACE_REVISION', 'PRIVATE_FACTOR_AUTHORING', 'FACTOR_CHAT_EVENT', 'FACTOR_PROPOSAL_OPERATION'));
ALTER TABLE product_command_receipt DROP CONSTRAINT product_command_receipt_outcome_id_check;
ALTER TABLE product_command_receipt ADD CONSTRAINT product_command_receipt_outcome_id_check CHECK (
    (outcome_kind IN ('RESEARCH_RUN', 'BACKTEST_RUN', 'INTEGRATION', 'CHART_CALCULATION_OPERATION')
        AND outcome_id ~ '^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$')
    OR (outcome_kind IN ('STRATEGY', 'STRATEGY_PROMOTION', 'QUALIFICATION_DECISION', 'SEARCH_EXPERIMENT', 'INTEGRATION_REVISION', 'WATCHLIST_REVISION', 'WORKSPACE_REVISION', 'PRIVATE_FACTOR_AUTHORING', 'FACTOR_CHAT_EVENT', 'FACTOR_PROPOSAL_OPERATION')
        AND outcome_id ~ '^[0-9a-f]{64}$')
);


-- Agent staging has no Factor/Research effect. Human confirmation owns the Authoring transaction.
CREATE TABLE factor_proposal_grant (grant_id UUID PRIMARY KEY, fingerprint TEXT UNIQUE NOT NULL CHECK(fingerprint ~ '^[0-9a-f]{64}$'), payload JSONB NOT NULL);
CREATE TABLE factor_proposal_revocation (grant_id UUID PRIMARY KEY REFERENCES factor_proposal_grant, command_id UUID UNIQUE NOT NULL REFERENCES product_command_receipt DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE factor_proposal_snapshot (fingerprint TEXT PRIMARY KEY CHECK(fingerprint ~ '^[0-9a-f]{64}$'), factor_id TEXT NOT NULL, grant_id UUID NOT NULL REFERENCES factor_proposal_grant, session_id UUID NOT NULL, event_fingerprint TEXT NOT NULL, payload JSONB NOT NULL, UNIQUE(factor_id,event_fingerprint));
CREATE TABLE factor_proposal_head (factor_id TEXT PRIMARY KEY, fingerprint TEXT NOT NULL REFERENCES factor_proposal_snapshot);
CREATE TABLE factor_proposal_operation (command_id UUID PRIMARY KEY REFERENCES product_command_receipt DEFERRABLE INITIALLY DEFERRED, fingerprint TEXT NOT NULL UNIQUE CHECK(fingerprint ~ '^[0-9a-f]{64}$'), payload JSONB NOT NULL);
CREATE TABLE factor_proposal_confirmation (proposal_fingerprint TEXT PRIMARY KEY REFERENCES factor_proposal_snapshot, command_id UUID UNIQUE NOT NULL REFERENCES product_command_receipt DEFERRABLE INITIALLY DEFERRED);
CREATE TRIGGER factor_proposal_grant_immutable BEFORE UPDATE OR DELETE OR TRUNCATE ON factor_proposal_grant FOR EACH STATEMENT EXECUTE FUNCTION private_asset_revision_immutable();
CREATE TRIGGER factor_proposal_revocation_immutable BEFORE UPDATE OR DELETE OR TRUNCATE ON factor_proposal_revocation FOR EACH STATEMENT EXECUTE FUNCTION private_asset_revision_immutable();
CREATE TRIGGER factor_proposal_snapshot_immutable BEFORE UPDATE OR DELETE OR TRUNCATE ON factor_proposal_snapshot FOR EACH STATEMENT EXECUTE FUNCTION private_asset_revision_immutable();
CREATE TRIGGER factor_proposal_operation_immutable BEFORE UPDATE OR DELETE OR TRUNCATE ON factor_proposal_operation FOR EACH STATEMENT EXECUTE FUNCTION private_asset_revision_immutable();
CREATE TRIGGER factor_proposal_confirmation_immutable BEFORE UPDATE OR DELETE OR TRUNCATE ON factor_proposal_confirmation FOR EACH STATEMENT EXECUTE FUNCTION private_asset_revision_immutable();
